 async function connect(){setError("");if(socket.current){manualDisconnect.current=true;if(retryTimer.current)window.clearTimeout(retryTimer.current);socket.current.close(1000,"Switching viewer target");socket.current=null;}manualDisconnect.current=false;attemptRef.current=0;try{const s=await request<Session>("/api/devices/connect",token,{device_id:partnerId,password:partnerPassword});const persisted:PersistedSession={sessionId:s.session_token,deviceId:s.device_id,viewerToken:s.session_token};sessionStorage.setItem(SESSION_STORAGE_KEY,JSON.stringify(persisted));setSession(s);openViewerSocket(s,0);}catch(e){const message=e instanceof Error?e.message:"Connection failed";setLastError(message);setStatus(message.toLowerCase().includes("offline")?"Host offline":message.toLowerCase().includes("password")?"Invalid/expired password":"Connection failed");setError(message);}}
 function sendControl(data:Record<string,unknown>,force=false){if((control||force)&&socket.current?.readyState===WebSocket.OPEN)socket.current.send(JSON.stringify({type:"control",...data}));}
 function sendText(value:string){if(value&&socket.current?.readyState===WebSocket.OPEN)socket.current.send(JSON.stringify({type:"text",text:value}));}
 function sendTextKey(key:string){if(socket.current?.readyState===WebSocket.OPEN)socket.current.send(JSON.stringify({type:"text",text:"",key}));}
 function sendClipboard(){if(clipboardText.length<=65536&&socket.current?.readyState===WebSocket.OPEN){socket.current.send(JSON.stringify({type:"clipboard_paste",request_id:crypto.randomUUID(),text:clipboardText}));setTransferStatus("Sending clipboard to host…");}}
 function sendWorkflowReplay(){const ws=socket.current;if(ws?.readyState!==WebSocket.OPEN||status!=="Connected (Live)"){setToast("Workflow replay requires an approved live session.");return;}ws.send(JSON.stringify({type:"control",event:"workflow_replay"}));setToast("Requesting replay of the latest host-local workflow…");}
 function togglePrivacy(){const ws=socket.current;if(status!=="Connected (Live)"){setToast("Waiting for host approval before changing host privacy settings.");return;}if(ws?.readyState===WebSocket.OPEN){ws.send(JSON.stringify({type:"control",event:"privacy_screen",enabled:!privacyEnabled,mode:"black"}));setToast("Updating host maintenance banner…");}}
 function requestRecordings(){const ws=socket.current;if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:"recording_list"}));}
 function deleteHostRecording(filename:string){if(socket.current?.readyState===WebSocket.OPEN)socket.current.send(JSON.stringify({type:"recording_delete",filename}));}
 function downloadHostRecording(filename:string){if(socket.current?.readyState!==WebSocket.OPEN)return;recordingDownloadRef.current={filename,chunks:[],offset:0,total:0,sha256:""};socket.current.send(JSON.stringify({type:"recording_download_chunk",filename,offset:0,length:131072}));setToast("Downloading recording in verified chunks…");}
 function toggleRecording(){const ws=socket.current;if(ws?.readyState!==WebSocket.OPEN||status!=="Connected (Live)"){setToast("Recording is available only after host approval.");return;}ws.send(JSON.stringify({type:"recording_control",action:recordingActive?"stop":"start",settings:{max_duration_seconds:Math.max(1,Math.min(240,recordingMaxMinutes))*60,retention_count:Math.max(1,Math.min(100,recordingRetention)),max_storage_mb:Math.max(100,Math.min(20480,recordingStorageMb)),save_mode:"local"}}));setToast(recordingActive?"Stopping local recording…":"Requesting explicit recording start…");}
 function handleDockPointerDown(e:ReactPointerEvent<HTMLButtonElement>){dockMoved.current=false;dockPointer.current={x:e.clientX,y:e.clientY,offsetX:dockOffset.x,offsetY:dockOffset.y};e.currentTarget.setPointerCapture(e.pointerId);}
 function handleDockPointerMove(e:ReactPointerEvent<HTMLButtonElement>){const p=dockPointer.current;if(!p)return;const dx=e.clientX-p.x,dy=e.clientY-p.y;if(Math.abs(dx)+Math.abs(dy)>6)dockMoved.current=true;if(dockMoved.current){const rect=e.currentTarget.parentElement?.getBoundingClientRect();const x=p.offsetX+dx,y=p.offsetY+dy;if(rect){setDockOffset({x:Math.max(p.offsetX-rect.left,Math.min(p.offsetX+window.innerWidth-rect.right,x)),y:Math.max(p.offsetY-rect.top,Math.min(p.offsetY+window.innerHeight-rect.bottom,y))});}else setDockOffset({x,y});}}
 function handleDockPointerUp(){if(!dockMoved.current)setDockOpen(v=>!v);dockPointer.current=null;}
 function formatRecordingTime(value:number){return String(Math.floor(value/60)).padStart(2,"0")+":"+String(value%60).padStart(2,"0");}
 function dispatchKeyboardValue(value:string){if(!value){lastInput.current="";return;}if(lastInput.current===value)return;lastInput.current=value;sendText(value);setKeyboardBuffer("");window.setTimeout(()=>{if(lastInput.current===value)lastInput.current="";},0);}
 function clampPan(x:number,y:number,z=zoom){const viewport=canvas.current?.parentElement;if(!viewport||!canvas.current)return {x:0,y:0};const maxX=Math.max(0,(canvas.current.offsetWidth*z-viewport.clientWidth)/2),maxY=Math.max(0,(canvas.current.offsetHeight*z-viewport.clientHeight)/2);return {x:Math.max(-maxX,Math.min(maxX,x)),y:Math.max(-maxY,Math.min(maxY,y))};}
 function changeZoom(value:number){const next=Math.max(1,Math.min(3,value));setZoom(next);const p=clampPan(panX,panY,next);setPanX(p.x);setPanY(p.y);}
 function updateVirtualCursor(x:number,y:number,visible=true){const cx=Math.min(1,Math.max(0,x)),cy=Math.min(1,Math.max(0,y));vCursorRef.current={x:cx,y:cy};setVCursor({x:cx,y:cy,visible});return {x:cx,y:cy};}
 function pointerDown(e:ReactPointerEvent<HTMLCanvasElement>){e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);pointerPoints.current.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointerPoints.current.size===2){if(gesture.current?.mode==="remote")sendControl({event:"mouse_up",button:0});const points=[...pointerPoints.current.values()];gesture.current={mode:"pinch",distance:Math.hypot(points[1].x-points[0].x,points[1].y-points[0].y),zoom,panX,panY,centerX:(points[0].x+points[1].x)/2,centerY:(points[0].y+points[1].y)/2};return;}if(e.pointerType==="touch"){if(!control)setControl(true);const p=viewerPoint(e.currentTarget,e.clientX,e.clientY);const cur=vCursor.visible?vCursorRef.current:updateVirtualCursor(p.x,p.y,true);gesture.current={mode:"touch_trackpad",startX:e.clientX,startY:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};if(!vCursor.visible)sendControl({event:"mouse_move",...cur},true);return;}if(zoom>1){gesture.current={mode:"pan",startX:e.clientX,startY:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};return;}gesture.current={mode:"remote",moved:false};const p=viewerPoint(e.currentTarget,e.clientX,e.clientY);updateVirtualCursor(p.x,p.y,false);sendControl({event:"mouse_move",...p});sendControl({event:"mouse_down",button:e.button,...p});}
 function pointerMove(e:ReactPointerEvent<HTMLCanvasElement>){if(pointerPoints.current.has(e.pointerId))pointerPoints.current.set(e.pointerId,{x:e.clientX,y:e.clientY});const g=gesture.current;if(pointerPoints.current.size>=2&&g?.mode==="pinch"){const points=[...pointerPoints.current.values()],distance=Math.max(1,Math.hypot(points[1].x-points[0].x,points[1].y-points[0].y)),centerX=(points[0].x+points[1].x)/2,centerY=(points[0].y+points[1].y)/2,next=Math.max(1,Math.min(3,g.zoom*distance/Math.max(1,g.distance)));setZoom(next);const p=clampPan(g.panX+centerX-g.centerX,g.panY+centerY-g.centerY,next);setPanX(p.x);setPanY(p.y);return;}if(g?.mode==="touch_trackpad"){const rect=e.currentTarget.getBoundingClientRect();const dx=(e.clientX-g.lastX)/Math.max(1,rect.width),dy=(e.clientY-g.lastY)/Math.max(1,rect.height);g.lastX=e.clientX;g.lastY=e.clientY;if(Math.hypot(e.clientX-g.startX,e.clientY-g.startY)>=6)g.moved=true;const next=updateVirtualCursor(vCursorRef.current.x+dx,vCursorRef.current.y+dy,true);sendControl({event:"mouse_move",...next},true);return;}if(g?.mode==="pan"){const dx=e.clientX-g.lastX,dy=e.clientY-g.lastY;g.lastX=e.clientX;g.lastY=e.clientY;if(Math.hypot(e.clientX-g.startX,e.clientY-g.startY)>=8)g.moved=true;const p=clampPan(panX+dx,panY+dy);setPanX(p.x);setPanY(p.y);return;}if(g?.mode==="remote"){const p=viewerPoint(e.currentTarget,e.clientX,e.clientY);sendControl({event:"mouse_move",...p});}}
 function pointerUp(e:ReactPointerEvent<HTMLCanvasElement>){e.preventDefault();const g=gesture.current;if(g?.mode==="touch_trackpad"){if(!g.moved){const cur=vCursorRef.current;sendControl({event:"mouse_move",...cur},true);sendControl({event:"mouse_down",button:0,...cur},true);sendControl({event:"mouse_up",button:0},true);}}else if(g?.mode==="remote")sendControl({event:"mouse_up",button:e.button});else if(g?.mode==="pan"&&!g.moved){const p=viewerPoint(e.currentTarget,e.clientX,e.clientY);sendControl({event:"mouse_move",...p});sendControl({event:"mouse_down",button:0,...p});sendControl({event:"mouse_up",button:0});}pointerPoints.current.delete(e.pointerId);if(pointerPoints.current.size===0)gesture.current=null;else if(pointerPoints.current.size===1&&zoom>1){const point=[...pointerPoints.current.values()][0];gesture.current={mode:"pan",startX:point.x,startY:point.y,lastX:point.x,lastY:point.y,moved:false};}else if(pointerPoints.current.size<2)gesture.current=null;if(e.currentTarget.hasPointerCapture(e.pointerId))e.currentTarget.releasePointerCapture(e.pointerId);}
 useEffect(()=>{if(!session||!token)return;const resume=()=>{if(document.visibilityState!=="visible")return;void request<Device[]>("/api/devices",token).then(setDevices).catch(()=>{});const ws=socket.current;if(ws?.readyState===WebSocket.OPEN){heartbeatSentAt.current=Date.now();ws.send(JSON.stringify({type:"heartbeat"}));if(resumeProbeTimer.current)window.clearTimeout(resumeProbeTimer.current);resumeProbeTimer.current=window.setTimeout(()=>{if(socket.current===ws&&ws.readyState===WebSocket.OPEN&&heartbeatSentAt.current>0)ws.close(4000,"Visibility resume heartbeat timed out");},2500);}else if(!manualDisconnect.current&&(!ws||ws.readyState===WebSocket.CLOSED)){if(retryTimer.current)window.clearTimeout(retryTimer.current);openViewerSocket(session,attemptRef.current+1);}};document.addEventListener("visibilitychange",resume);return()=>document.removeEventListener("visibilitychange",resume);},[session,token]);
 async function sendSelectedFile(){
  try{const file=fileInput.current?.files?.[0],ws=socket.current;if(!file||!ws||ws.readyState!==WebSocket.OPEN)return;if(file.size<=0||file.size>50*1024*1024)throw new Error("Choose a file between 1 byte and 50 MB");const digest=await crypto.subtle.digest("SHA-256",await file.arrayBuffer());const sha256=Array.from(new Uint8Array(digest)).map(v=>v.toString(16).padStart(2,"0")).join("");const transfer:ActiveTransfer={transfer_id:crypto.randomUUID(),name:file.name,total_size:file.size,sha256,chunk_size:256*1024,compression:useZstd?"zstd":"none",ackedOffset:0,file,updatedAt:Date.now()};await saveTransfer(transfer);activeTransfer.current=transfer;pendingFile.current=file;transferOffset.current=0;setTransferProgress(0);setTransferVerified(false);ws.send(JSON.stringify({type:"transfer_init",transfer_id:transfer.transfer_id,name:transfer.name,total_size:transfer.total_size,sha256,chunk_size:transfer.chunk_size,compression:transfer.compression}));setTransferStatus("Waiting for host destination selection and resume offset…");}catch(error){setTransferStatus(error instanceof Error?error.message:"Unable to initialize transfer");}
 }
 async function uploadPendingFile(offset:number){const transfer=activeTransfer.current,file=pendingFile.current,ws=socket.current;if(!transfer||!file||!ws||ws.readyState!==WebSocket.OPEN||transferPaused)return;try{if(offset>=transfer.total_size){ws.send(JSON.stringify({type:"transfer_complete",transfer_id:transfer.transfer_id}));setTransferStatus("Awaiting receiver SHA-256 verification…");return;}const raw=new Uint8Array(await file.slice(offset,Math.min(file.size,offset+transfer.chunk_size)).arrayBuffer());let payload=raw;if(transfer.compression==="zstd"){await initZstd();payload=zstdCompress(raw,3);if(payload.byteLength>1024*1024)throw new Error("Compressed chunk exceeds relay frame limit");}let binary="";for(let i=0;i<payload.length;i+=0x8000)binary+=String.fromCharCode(...payload.subarray(i,Math.min(i+0x8000,payload.length)));ws.send(JSON.stringify({type:"transfer_chunk",transfer_id:transfer.transfer_id,offset,data:btoa(binary)}));setTransferStatus("Transferring "+Math.round(offset/transfer.total_size*100)+"% — awaiting chunk acknowledgement");}catch(error){setTransferStatus(error instanceof Error?error.message:"Chunk compression or send failed");}}
 useEffect(()=>{void loadTransfer().then(saved=>{if(!saved)return;activeTransfer.current=saved;pendingFile.current=new File([saved.file],saved.name);transferOffset.current=saved.ackedOffset;setTransferProgress(Math.min(100,Math.floor(saved.ackedOffset/Math.max(1,saved.total_size)*100)));setTransferStatus("Restored interrupted transfer; reconnect to resume from acknowledged offset.");}).catch(error=>setTransferStatus(error instanceof Error?error.message:"Could not restore transfer state"));},[]);

 async function loadCommunity(){
  if(!token)return;
  setCommunityLoading(true);setWorkflowMessage("");
  try{setCommunityWorkflows(await request<any[]>("/api/workflows/community",token));}
  catch(e){setWorkflowMessage(e instanceof Error?e.message:"Could not load community workflows");}
  finally{setCommunityLoading(false);}
 }
 async function publishSelectedWorkflow(){
  if(!workflowFile||!publishOptIn||!token)return;
  try{
   if(workflowFile.size>2000000)throw new Error("Workflow JSON must be smaller than 2 MB.");
   const source=JSON.parse(await workflowFile.text());
   if(source.privacy?.typed_text_recorded||source.privacy?.clipboard_recorded)throw new Error("This workflow contains sensitive input data and cannot be published.");
   const publicWorkflow={...source,is_public:true,privacy:{typed_text_recorded:false,clipboard_recorded:false,local_only:false}};
   const result=await request<{id:number;name:string}>("/api/workflows/publish",token,{workflow:publicWorkflow});
   setWorkflowMessage("Published to Community Library: "+result.name);
   setPublishOptIn(false);setWorkflowFile(null);
   await loadCommunity();
  }catch(e){setWorkflowMessage(e instanceof Error?e.message:"Publishing failed");}
 }
 async function importCommunityWorkflow(id:number){
  try{
   const result=await request<{workflow:Record<string,unknown>}>("/api/workflows/import/"+id,token,{});
   const blob=new Blob([JSON.stringify(result.workflow,null,2)],{type:"application/json"});
   const url=URL.createObjectURL(blob);const anchor=document.createElement("a");
   anchor.href=url;anchor.download=String(result.workflow.name||"community-workflow")+".json";
   document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);
   setWorkflowMessage("Imported workflow JSON downloaded. Save it in the agent's local workflows folder to replay.");
  }catch(e){setWorkflowMessage(e instanceof Error?e.message:"Import failed");}
 }

 function disconnect(explicitEnd=true){manualDisconnect.current=true;if(retryTimer.current)window.clearTimeout(retryTimer.current);if(heartbeatTimer.current)window.clearInterval(heartbeatTimer.current);if(explicitEnd){sessionStorage.removeItem(SESSION_STORAGE_KEY);if(socket.current?.readyState===WebSocket.OPEN)socket.current.send(JSON.stringify({type:"viewer_end"}));}socket.current?.close(1000,explicitEnd?"Viewer ended session":"Viewer signed out");socket.current=null;setSession(null);setControl(false);setPrivacyEnabled(false);setRecordingActive(false);setStatus("Ready to connect");setLatency(null);}
 function logout(){disconnect(false);localStorage.removeItem("rdp-token");setToken("");setUser(null);}
